#!/usr/bin/env python3
"""Offline native-scale reviewer. Captures remain at original pixel dimensions."""
import json,html
from pathlib import Path
HERE=Path(__file__).resolve().parent
m=json.loads((HERE/'manifest.json').read_text())
groups={}
for c in m['captures']:groups.setdefault((c['arm'],c['width'],c['scene']),[]).append(c)
links=''
for (arm,width,scene),frames in groups.items():
 links+=f'<details><summary>{arm} · {width} · {scene} · {len(frames)} кадров</summary><ol>'
 for c in frames:links+=f'<li><a href="captures/{c["file"]}">{c["file"]}</a> · scrollY {c["scrollY"]:.2f}</li>'
 links+='</ol></details>'
doc='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>0524.W4.R — R1.P full LANDING preservation</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#070709;color:#f1f1f4;font:16px/1.6 system-ui,sans-serif}header,main>p,aside,details{padding:12px 24px;max-width:1450px}h1{font-size:26px;margin:8px 0}a{color:#ff7180}button,select{font:inherit;background:#101218;color:#f1f1f4;border:1px solid #555b68;padding:8px 12px;border-radius:0;min-height:44px}button[aria-pressed=true]{border:2px solid #ff2034}label{display:inline-grid;gap:4px}nav{display:flex;gap:12px;flex-wrap:wrap;align-items:end;padding:12px 24px;background:#101218;border-block:1px solid #262830}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #f1f1f4;outline-offset:3px}.warning{color:#ff7180}#meta{font:14px/1.6 monospace;overflow-wrap:anywhere}figure{margin:12px 0}#canvas{width:100%;overflow:auto;border-block:1px solid #555b68;background:#101218}#frame{display:block;max-width:none;width:auto;height:auto}figcaption{padding:12px 24px}small{color:#b4b8c3}.all{padding:12px 24px}summary{cursor:pointer}aside{border-left:3px solid #ff2034;margin:22px 24px}code{overflow-wrap:anywhere}
</style></head><body><header><p class="warning">R1.P / PROPOSED · Gate R-A CHANGES REQUESTED · R2 NOT AUTHORIZED</p><h1>A+ внутри полной существующей LANDING</h1><p>Один вариант: исходный архивный комплекс, четыре полных SYSTEM SURFACES в WORK, три разных последствия, оригинальная карта и полноразмерные персонажи.</p><p><a href="../../waves/w4rp/PRESERVATION_MATRIX.md">Матрица сохранения</a> · <a href="../../waves/w4rp/R1P_HANDOFF.md">Решения и воспроизведение</a> · <a href="manifest.json">346 кадров / raw manifest</a> · <a href="source-validation.json">Источник</a> · <a href="probe-validation.json">Prototype QA</a></p></header>
<nav aria-label="Выбор полноразмерного сравнения"><label>Viewport<select id="vp"><option value="1440">1440 × 900</option><option value="1920">1920 × 1080</option><option value="390">390 × 844</option><option value="360">360 × 800</option></select></label><label>Сцена<select id="scene"><option value="surfaces">Four Surfaces · полная композиция</option><option value="work">WORK · архив + место вставки + соседняя секция</option><option value="doctrine">BLACK SUN · четыре такта + полный архив</option><option value="aftermath">WHAT REMAINS · вся секция</option><option value="world">WORLD GRID · W04 + карта + OMEGA-0</option><option value="characters">CHARACTERS · полные портреты + AXIOM ∅</option><option value="work02">WORK 02 · WATCH_DOG</option><option value="work03">WORK 03 · CHRONICLE</option><option value="work05">WORK 05 · CONTENT</option><option value="work02-disclosure">CURRENT · раскрытие 02</option><option value="work03-disclosure">CURRENT · раскрытие 03</option><option value="work05-disclosure">CURRENT · раскрытие 05</option></select></label><div id="arms"><button data-arm="before" aria-pressed="false">BEFORE · 6b082e5</button> <button data-arm="current" aria-pressed="false">W4 CURRENT · b85fbb0</button> <button data-arm="aplus" aria-pressed="true">A+ PROPOSED</button></div><label>Кадр<select id="segment"></select></label><button id="prev" aria-label="Предыдущий кадр">←</button><button id="next" aria-label="Следующий кадр">→</button></nav>
<main><p id="explain"></p><p id="meta" aria-live="polite"></p><figure><div id="canvas"><img id="frame" alt=""></div><figcaption><a id="native" href="">Открыть нативный файл отдельно</a> · 1 CSS px = 1 capture px при 100% browser zoom. Изображение не уменьшается по ширине окна; доступна горизонтальная прокрутка.</figcaption></figure><aside>Каждая версия снята из своей полной страницы. Кадры идут непрерывно с перекрытием, включая соседние секции. Номер кадра — положение в соответствующей секции, не совпадение scrollY между разными по длине текстами. Подписи в кадрах и старые ложные статусы BEFORE сохранены для сравнения.<br>Four Surfaces: BEFORE показывает исходный #modules в WORLD; CURRENT — его трёхколоночную смысловую замену WHAT REMAINS. Полные упрощённые disclosures CURRENT доступны отдельными сценами 02/03/05. A+ показывает восстановленную экспозицию после реального архива внутри WORK. Это разные роли, а не три реализации одной секции.<br>R1.P не подтверждает R3/G4/performance и не является художественным approval.</aside><div class="all"><h2>Все нативные кадры</h2>'''+links+'''</div></main><script>
const frames=__DATA__, $=id=>document.getElementById(id);let arm='aplus',list=[];
const q=new URLSearchParams(location.hash.slice(1));if(q.has('width'))$('vp').value=q.get('width');if(q.has('scene'))$('scene').value=q.get('scene');if(['before','current','aplus'].includes(q.get('arm')))arm=q.get('arm');let selected=Math.max(0,Number(q.get('frame')||1)-1);
function show(){const i=Math.min(selected,list.length-1);selected=Math.max(0,i);$('segment').value=selected;const c=list[selected];if(!c)return;const src='captures/'+c.file;$('frame').src=src;$('frame').width=c.width;$('frame').height=c.height;$('frame').alt=`${c.arm}, ${c.width}×${c.height}, ${c.scene}, кадр ${c.segment} из ${c.total}`;$('native').href=src;$('meta').textContent=`${c.arm} · ${c.width}×${c.height} · DPR 1 · ${c.scene} · ${c.segment}/${c.total} · scrollY ${c.scrollY.toFixed(2)} · SHA256 ${c.sha256}`;document.querySelectorAll('[data-arm]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.arm===arm)));history.replaceState(null,'','#width='+c.width+'&scene='+$('scene').value+'&arm='+arm+'&frame='+(selected+1));}
function route(){let scene=$('scene').value,width=Number($('vp').value),actual=scene;if(scene==='surfaces'&&arm!=='aplus')actual='aftermath';if(scene.endsWith('-disclosure'))arm='current';list=frames.filter(c=>c.width===width&&c.arm===arm&&c.scene===actual);$('segment').innerHTML=list.map((c,i)=>`<option value="${i}">${i+1} / ${list.length}</option>`).join('');$('explain').textContent=scene==='surfaces'?(arm==='aplus'?'A+ — все четыре исходные композиции в WORK после настоящих интерфейсов.':'BEFORE — исходные Four Surfaces в WORLD. CURRENT — WHAT REMAINS на их прежнем месте; disclosures смотрите в отдельных сценах.'):scene.endsWith('-disclosure')?'Только CURRENT, раскрытие открыто. Эти кадры имеют отдельное состояние и не объявляются paired closed-state comparison.':'Полный проход секции с естественными соседями; галерея01, карта02.01, dialogs closed, reduced motion. Для WORK02/03/05 выбор соответствует номеру сцены.';show();}
for(const id of ['vp','scene'])$(id).addEventListener('change',()=>{selected=0;route()});document.querySelectorAll('[data-arm]').forEach(b=>b.onclick=()=>{arm=b.dataset.arm;selected=0;route()});$('segment').onchange=()=>{selected=Number($('segment').value);show()};$('prev').onclick=()=>{selected=(selected-1+list.length)%list.length;show()};$('next').onclick=()=>{selected=(selected+1)%list.length;show()};route();
</script></body></html>'''
doc=doc.replace('__DATA__',json.dumps(m['captures'],ensure_ascii=False).replace('</','<\\/'))
(HERE/'REVIEW.html').write_text(doc)
print('Built native reviewer with',len(m['captures']),'direct artifact links')
